CREATE TABLE IF NOT EXISTS clientes_comerciales(clc_id BIGSERIAL PRIMARY KEY,cli_id BIGINT NOT NULL,per_id BIGINT NOT NULL,clc_cod VARCHAR(30) NOT NULL,clc_fec_alt DATE NOT NULL,clc_est VARCHAR(20) NOT NULL,clc_tar VARCHAR(50),clc_for_pag VARCHAR(50),clc_con_pag VARCHAR(100),dom_id_fac BIGINT,clc_nom_fis VARCHAR(150),clc_nif_fis VARCHAR(30),clc_obs VARCHAR(500),clc_usu_mov VARCHAR(100) NOT NULL,clc_fec_mov TIMESTAMP NOT NULL,clc_act BOOLEAN NOT NULL,CONSTRAINT uk_cliente_comercial_persona UNIQUE(cli_id,per_id),CONSTRAINT uk_cliente_comercial_codigo UNIQUE(cli_id,clc_cod));
